<script setup>
import { useCustomerPresentation } from '../../Composables/customerPresentation';
const { customerText } = useCustomerPresentation();
import {Head,useForm} from '@inertiajs/vue3';import CustomerShell from '../../Components/CustomerShell.vue';const form=useForm({phone:''});const submit=()=>{if(!form.processing)form.put('/account/phone')};</script><template><Head :title="customerText(&quot;pages.auth.completephone.attribute.title.21930b90&quot;, &quot;Lengkapi nomor telepon&quot;)"/><CustomerShell compact-footer><main class="lf-auth-wrap"><form class="lf-auth-card" @submit.prevent="submit"><p class="lf-eyebrow">{{ customerText("pages.auth.completephone.478c7fe1", "Lengkapi akun") }}</p><h1>{{ customerText("pages.auth.completephone.a30deaad", "Nomor telepon") }}</h1><p>{{ customerText("pages.auth.completephone.ba5de30b", "Lengkapi nomor telepon untuk kontak pesanan sebelum memakai akun LFAMILIA.") }}</p><label class="text-[10px] font-semibold text-white/70">{{ customerText("pages.auth.completephone.a30deaad", "Nomor telepon") }}<input v-model="form.phone" type="tel" name="phone" autocomplete="tel" :placeholder="customerText(&quot;pages.auth.completephone.attribute.placeholder.a02514d1&quot;, &quot;Contoh: 081234567890&quot;)" :aria-invalid="Boolean(form.errors.phone)" required></label><span role="alert" v-if="form.errors.phone" class="mt-1 block text-[9px] text-red-300">{{form.errors.phone}}</span><button type="submit" class="lf-primary mt-3 w-full" :disabled="form.processing">{{form.processing?'Menyimpan…':'Simpan nomor'}}</button></form></main></CustomerShell></template>